-- Hand edit (b): past-day sessions are closed at their day boundary (L07).
UPDATE "opening_sessions" SET "closed_at" = (("session_date"::date + 1)::timestamp AT TIME ZONE 'Africa/Johannesburg') WHERE "closed_at" IS NULL AND "session_date"::date < (now() AT TIME ZONE 'Africa/Johannesburg')::date;--> statement-breakpoint
-- Hand edit (c): today's sessions are not guessed at. More than one still open
-- means a human closes them first; the migration (one transaction) changes nothing.
DO $$
BEGIN
  IF (SELECT count(*) FROM "opening_sessions" WHERE "closed_at" IS NULL) > 1 THEN
    RAISE EXCEPTION 'AT-204/0036: more than one opening_sessions row from today or later is open; close all but one (set closed_at) before migrating — nothing changed';
  END IF;
END $$;--> statement-breakpoint
CREATE UNIQUE INDEX "opening_sessions_one_open" ON "opening_sessions" USING btree ("tenant_id") WHERE closed_at IS NULL;